/// The text before the first space, or the whole line.
fn first_word(line: &str) -> &str {
    match line.find(' ') {
        Some(i) => &line[..i],
        None => line,
    }
}

/// The last `n` entries, or all of them if there are fewer.
fn last_n(entries: &[u32], n: usize) -> &[u32] {
    let start = entries.len().saturating_sub(n);
    &entries[start..]
}

/// Adds `bonus` to every share, in place.
fn add_bonus(shares: &mut [u32], bonus: u32) {
    for s in shares.iter_mut() {
        *s += bonus;
    }
}

fn main() {
    let line = String::from("gold 30");
    println!("{}", first_word(&line));
    let mut shares = vec![5, 10, 20, 40];
    add_bonus(&mut shares[1..], 1);
    println!("{:?}", last_n(&shares, 2));
}

