    }

    #[test]
    fn last_n_takes_the_tail() {
        let v = [1, 2, 3, 4, 5];
        let t = last_n(&v, 2);
        assert_eq!(t, &[4, 5]);
        assert!(std::ptr::eq(t.as_ptr(), v[3..].as_ptr()));
    }

    #[test]
    fn last_n_larger_than_len_gives_everything() {
        assert_eq!(last_n(&[7, 8], 5), &[7, 8]);
    }

