fn find_entry<'a>(ledger: &'a [String], prefix: &str) -> Option<&'a str> {
    ledger
        .iter()
        .find(|entry| entry.starts_with(prefix))
        .map(|entry| entry.as_str())
}

fn main() {
    let ledger = vec![String::from("gold: 30"), String::from("rum: 12")];
    println!("{:?}", find_entry(&ledger, "rum"));
}

