#[cfg(test)]
mod hidden_tests {
    use super::*;

    fn v(entries: &[&str]) -> Vec<String> {
        entries.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn finds_the_matching_entry() {
        let ledger = v(&["gold: 30", "rum: 12", "maps: 1"]);
        assert_eq!(find_entry(&ledger, "rum"), Some("rum: 12"));
    }

    #[test]
    fn returns_the_first_of_several_matches() {
        let ledger = v(&["rum: 1", "gold: 30", "rum: 2"]);
        assert_eq!(find_entry(&ledger, "rum"), Some("rum: 1"));
    }

    #[test]
    fn missing_prefix_gives_none() {
        let ledger = v(&["gold: 30"]);
        assert_eq!(find_entry(&ledger, "silk"), None);
        assert_eq!(find_entry(&[], "gold"), None);
    }

    #[test]
    fn empty_prefix_matches_the_first_entry() {
        let ledger = v(&["gold: 30", "rum: 12"]);
        assert_eq!(find_entry(&ledger, ""), Some("gold: 30"));
    }

    #[test]
    fn result_borrows_from_the_ledger() {
        let ledger = v(&["gold: 30", "rum: 12"]);
        let found = find_entry(&ledger, "rum").unwrap();
        assert!(std::ptr::eq(found.as_ptr(), ledger[1].as_ptr()));
    }

    #[test]
    fn result_outlives_the_prefix() {
        let ledger = v(&["gold: 30", "rum: 12"]);
        let found;
        {
            let shout = String::from("gold");
            found = find_entry(&ledger, &shout);
        }
        assert_eq!(found, Some("gold: 30"));
    }
}

