use std::io::{self, Read};

// Parses "name: amount" lines. Lines that don't parse are skipped.
fn parse(text: &str) -> Vec<(&str, u32)> {
    let mut out = Vec::new();
    for line in text.lines() {
        if let Some((name, amount)) = line.split_once(':') {
            if let Ok(n) = amount.trim().parse() {
                out.push((name.trim(), n));
            }
        }
    }
    out
}

// Adds `amount` to the total for `name`, or appends a new total.
fn credit(totals: &mut Vec<(&str, u32)>, name: &str, amount: u32) {
    for t in totals.iter_mut() {
        if t.0 == name {
            t.1 += amount;
            return;
        }
    }
    totals.push((name, amount));
}

// The name with the biggest total. Ties keep the first.
fn richest(totals: &[(&str, u32)]) -> Option<&str> {
    let mut best: Option<(&str, u32)> = None;
    for &(name, total) in totals {
        match best {
            Some((_, b)) if b >= total => {}
            _ => best = Some((name, total)),
        }
    }
    best.map(|(name, _)| name)
}

// "name xN", e.g. "gold x35".
fn label(name: &str, total: u32) -> &str {
    let s = format!("{name} x{total}");
    &s
}

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).unwrap();
    let entries = parse(&text);
    println!("entries: {}", entries.len());
    let mut totals = Vec::new();
    for (name, amount) in entries {
        credit(&mut totals, name, amount);
    }
    let top = richest(&totals);
    for (_, total) in &totals {
        credit(&mut totals, "fleet", *total);
    }
    for (name, total) in &totals {
        println!("{}", label(name, *total));
    }
    println!("richest: {}", top.unwrap_or("none"));
}

